import type { JSX } from "react";

/**
 * Refração de borda "Liquid Glass" de verdade (feDisplacementMap) pra home de vendas
 * (automesa.com.br) — mesma técnica já usada em /r/[slug] e /reservas, calibrada do mesmo jeito
 * (scale acompanhando o bezel, ver referência de física da skill liquid-glass).
 */
export function DefinicoesDoVidroLiquidoSite(): JSX.Element {
  return (
    <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true">
      <defs>
        <filter id="vidro-hero-site" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispHeroSite" x="0" y="0" width="380" height="420" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispHeroSite" scale="-36" xChannelSelector="R" yChannelSelector="G" />
        </filter>
        <filter id="vidro-feature-site" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispFeatureSite" x="0" y="0" width="320" height="200" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispFeatureSite" scale="-24" xChannelSelector="R" yChannelSelector="G" />
        </filter>
      </defs>
    </svg>
  );
}
